/* Small offline Markdown renderer for headings, emphasis, lists, code and links. */
(function(){function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}function inline(s){return s.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>')}function parse(md){md=esc(String(md||''));var lines=md.split(/\r?\n/),out=[],list=false,code=false,buf=[];for(var l of lines){if(/^```/.test(l)){if(code){out.push('<pre><code>'+buf.join('\n')+'</code></pre>');buf=[]}code=!code;continue}if(code){buf.push(l);continue}var m=l.match(/^(#{1,3})\s+(.*)$/);if(m){if(list){out.push('</ul>');list=false}out.push('<h'+m[1].length+'>'+inline(m[2])+'</h'+m[1].length+'>');continue}m=l.match(/^[-*]\s+(.*)$/);if(m){if(!list){out.push('<ul>');list=true}out.push('<li>'+inline(m[1])+'</li>');continue}if(list){out.push('</ul>');list=false}if(/^>\s?/.test(l)){out.push('<blockquote>'+inline(l.replace(/^>\s?/,''))+'</blockquote>')}else if(l.trim())out.push('<p>'+inline(l)+'</p>')}if(list)out.push('</ul>');if(code)out.push('<pre><code>'+buf.join('\n')+'</code></pre>');return out.join('')}window.marked={parse:parse}})();
